<?php require_once __DIR__.'/app/core/bootstrap.php'; $title='Tours & Safaris'; $tours=query("SELECT t.*,d.name destination FROM tours t LEFT JOIN destinations d ON d.id=t.destination_id WHERE t.status IN ('active','pending') ORDER BY t.status='active' DESC,t.featured DESC,t.id DESC")->fetch_all(MYSQLI_ASSOC); require __DIR__.'/app/views/header.php'; ?>
<section class="section"><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Wildvista collection</div><h2>Tours & Safaris</h2><p class="muted">Explore Arusha through curated experiences. Pending listings are clearly marked and are not bookable.</p></div></div><div class="grid"><?php foreach($tours as $t): ?><article class="card"><div class="card-img"><img src="<?=e(media_url($t['image']))?>" alt=""></div><div class="card-body"><div class="meta"><span><?=$t['duration_days']?> day<?=($t['duration_days']!=1?'s':'')?></span><span><?=e($t['destination']??'Arusha')?></span><?php if($t['status']==='active'): ?><span class="tag">Available</span><?php else: ?><span class="tag pending">Pending</span><?php endif; ?></div><h3><?=e($t['title'])?></h3><p class="muted"><?=e($t['short_description'])?></p><div class="row-between"><span class="price">From <?=money((float)$t['base_price'])?></span><?php if($t['status']==='active'): ?><a class="btn btn-dark" href="<?=url('tour.php?id='.$t['id'])?>">View trip</a><?php else: ?><span class="muted">Coming soon</span><?php endif; ?></div></div></article><?php endforeach; ?></div></section>
<?php require __DIR__.'/app/views/footer.php'; ?>
